function hpeManualOffline(){return !!hpeProfile&&localStorage.getItem('hpe-manual-offline-'+hpeProfile.id)==='true'}
window.hpeNetworkAllowed=()=>navigator.onLine&&!hpeManualOffline();
window.hpeSetOffline=async enabled=>{
 if(!hpeProfile)return;
 if(enabled){await hpePrepareOffline();if(!$('#hpeOfflineStatus').textContent.startsWith('App baixado')){hpeOpenConnection();return}localStorage.setItem('hpe-manual-offline-'+hpeProfile.id,'true');hpeOfflineMode=true;save()}
 else{localStorage.removeItem('hpe-manual-offline-'+hpeProfile.id);if(navigator.onLine)await hpeReconnectOffline();else hpeOfflineMode=true}
 render();hpeOpenConnection();
};
function hpeModeText(){return hpeManualOffline()?'Modo offline ativado':navigator.onLine?'Modo online':'Sem conexão · dados locais'}
window.hpeOpenConnection=()=>modal(`<section class="connection-panel"><span class="eyebrow">SEU MODO DE USO</span><h2>${hpeModeText()}</h2><label class="mode-switch"><span><b>Usar offline</b><small>Treinos e registros salvos neste aparelho.</small></span><input type="checkbox" role="switch" aria-label="Usar offline" ${hpeManualOffline()?'checked':''} onchange="this.disabled=true;hpeSetOffline(this.checked)"></label><p>${hpeManualOffline()?'Desative para voltar ao modo online e enviar seus registros.':'Online é o padrão. Ative antes de entrar em uma academia sem sinal.'}</p><p class="note">O primeiro acesso e o download precisam de internet. Vídeos externos, novos cadastros e recuperação de senha precisam de conexão.</p><p role="status">${esc($('#hpeOfflineStatus').textContent)}</p><button onclick="hpeOpenPreferences()">Ver configurações e sincronização</button></section>`);
function hpeLogs(){return data.logs.filter(l=>l.student===student).slice().sort((a,b)=>new Date(b.date)-new Date(a.date))}
function hpeSessionMetrics(log){const entries=log.seriesEntries||[];return {sets:entries.length,reps:entries.filter(e=>e.unit!=='s').reduce((n,e)=>n+Number(e.reps||0),0),volume:entries.filter(e=>e.unit!=='s').reduce((n,e)=>n+Number(e.weight||0)*Number(e.reps||0),0),names:[...new Set(entries.map(e=>e.name))]}}
function hpeNumber(n){return Number(n).toLocaleString('pt-BR',{maximumFractionDigits:1})}
window.hpeShowReport=index=>{const log=hpeLogs()[index];if(!log)return;const m=hpeSessionMetrics(log);modal(`<section class="workout-report"><span class="eyebrow">TREINO CONCLUÍDO · ${new Date(log.date).toLocaleDateString('pt-BR')}</span><h2>${esc(log.title||'Seu treino do dia')}</h2><p>Você fez mais um registro na sua evolução.</p><div class="report-stats"><div><b>${log.durationSeconds?clockText(log.durationSeconds):'—'}</b><span>Duração</span></div><div><b>${log.count||m.names.length}</b><span>Exercícios</span></div><div><b>${m.sets||'—'}</b><span>Séries</span></div><div><b>${hpeNumber(m.volume)} kg</b><span>Volume registrado</span></div></div><p class="note">Volume = carga × repetições registradas; séries por tempo não entram nesta soma.</p>${m.names.map(name=>`<div class="report-exercise"><h3>${esc(name)}</h3>${log.seriesEntries.filter(e=>e.name===name).map(e=>`<div class="listrow"><span>Série ${e.set}</span><b>${hpeNumber(e.weight)} kg × ${e.reps} ${e.unit==='s'?'seg':'reps'}</b></div>`).join('')}</div>`).join('')||'<p>Este registro antigo não possui detalhes das séries.</p>'}<p><b>Esforço:</b> ${log.effort}/10</p>${log.note?`<p><b>Como foi:</b> ${esc(log.note)}</p>`:''}<button class="primary" onclick="$('#modal').close();go('historico')">Acompanhar minhas cargas ↗</button></section>`)};
function hpeHistoryPage(){const logs=hpeLogs(),names=[...new Set(logs.flatMap(l=>(l.seriesEntries||[]).map(e=>e.name)))].sort();return heading('SEU PROGRESSO','Cada treino deixa uma marca.','Reveja suas sessões e compare as cargas do mesmo exercício.')+`<section class="card"><div class="row"><h2>Evolução das cargas</h2><select aria-label="Exercício do histórico" onchange="hpeLoadGraph(this.value)">${names.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}</select></div><div id="hpeLoadGraph">${names.length?hpeLoadGraphHtml(names[0]):'<p>Registre suas séries e conclua um treino para começar seu histórico.</p>'}</div></section><section class="card"><h2>Meus relatórios</h2>${logs.map((l,i)=>{const m=hpeSessionMetrics(l);return `<div class="history-session"><div><b>${new Date(l.date).toLocaleDateString('pt-BR')} · ${esc(l.title||'Treino')}</b><p>${l.count} exercícios · ${m.sets||'—'} séries · ${l.durationSeconds?clockText(l.durationSeconds):'Duração não registrada'}</p></div><button onclick="hpeShowReport(${i})">Ver relatório ↗</button></div>`}).join('')||'<p>Seu primeiro relatório aparecerá ao concluir o treino.</p>'}</section>`}
function hpeLoadGraphHtml(name){const sessions=hpeLogs().filter(l=>l.seriesEntries?.some(e=>e.name===name)).reverse();const points=sessions.map(l=>({log:l,entries:l.seriesEntries.filter(e=>e.name===name)}));const max=Math.max(1,...points.map(p=>Math.max(...p.entries.map(e=>Number(e.weight)||0))));return `<p class="note">Maior carga registrada por sessão. Compare também repetições e técnica com seu personal.</p><div class="load-timeline">${points.map(p=>{const weight=Math.max(...p.entries.map(e=>Number(e.weight)||0));return `<div class="load-point"><time>${new Date(p.log.date).toLocaleDateString('pt-BR')}</time><div class="load-track"><span style="width:${weight/max*100}%"></span></div><b>${hpeNumber(weight)} kg</b><small>${p.entries.map(e=>`${e.weight} kg × ${e.reps} ${e.unit==='s'?'seg':'reps'}`).join(' · ')}</small></div>`}).join('')}</div>`}
window.hpeLoadGraph=name=>{$('#hpeLoadGraph').innerHTML=hpeLoadGraphHtml(name)};
const experienceFinish=window.finish;window.finish=()=>{experienceFinish();const form=$('#finishForm');if(!form||!$('#modal').open)return;const submit=form.onsubmit;form.onsubmit=e=>{const count=data.logs.length;submit(e);if(data.logs.length>count)hpeShowReport(0)}};
const experienceReady=hpeOfflineSessionReady;hpeOfflineSessionReady=function(profile){experienceReady(profile);if(hpeManualOffline()){hpeOfflineMode=true;if(hpeSyncOwner!==profile.id){hpeSyncOwner=profile.id;let meta;try{meta=JSON.parse(localStorage.getItem('hpe-sync-meta-'+profile.id))}catch{}hpeSyncRevision=meta?.revision||0;hpeSyncDirty=!!meta?.dirty;hpeSyncReady=false}if(hpeSharedOwner!==profile.id){hpeSharedOwner=profile.id;try{hpeSharedCache=JSON.parse(localStorage.getItem('hpe-shared-meta-'+profile.id))||{}}catch{}hpeSharedReady=false}}};
const experienceRender=render;render=function(){experienceRender();if(document.body.classList.contains('signed-out'))return;$('#nav').insertAdjacentHTML('beforeend',`<button onclick="hpeOpenConnection()">${hpeManualOffline()?'◉':'◎'} &nbsp; ${hpeModeText()}</button>`);if(role!=='aluno')return;$('#nav').insertAdjacentHTML('beforeend',`<button class="${page==='historico'?'active':''}" onclick="go('historico')">↗ &nbsp; Relatórios e cargas</button>`);if(page==='historico')$('#content').innerHTML=hpeHistoryPage();if(page==='inicio'){$('#content').children[0]?.insertAdjacentHTML('afterend',`<section class="student-shortcuts"><button class="primary" onclick="go('treinos')">▶ Meu treino</button><button onclick="go('historico')">↗ Relatórios e cargas</button><button onclick="hpeOpenConnection()">${hpeModeText()}</button></section>`);const last=hpeLogs()[0];if(last)$('#content').insertAdjacentHTML('beforeend',`<section class="card"><span class="eyebrow">ÚLTIMO TREINO</span><h2>${esc(last.title||'Seu treino')}</h2><p>${new Date(last.date).toLocaleDateString('pt-BR')} · ${last.count} exercícios</p><button onclick="hpeShowReport(0)">Ver meu relatório ↗</button></section>`)} };

if(!document.body.classList.contains('signed-out'))render();
